<?php
declare(strict_types=1);
require_once __DIR__.'/project-templates.php';
require_once __DIR__.'/admin-shell.php';
$user=(string)(getenv('ADMIN_USERNAME')?:''); $password=(string)(getenv('ADMIN_PASSWORD')?:'');
if($user===''||$password===''||!hash_equals($user,(string)($_SERVER['PHP_AUTH_USER']??''))||!hash_equals($password,(string)($_SERVER['PHP_AUTH_PW']??''))) { header('WWW-Authenticate: Basic realm="Grzywniak Discovery"'); http_response_code(401); exit('Authentication required.'); }
header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store');
$active=projectTemplates(); $proposed=projectTemplates('proposed');
function catalogEsc(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
?><!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Katalog szablonów · Grzywniak</title><?=adminShellStyles()?><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#090e18;color:#eaf0fa;font:14px/1.55 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:38px 21px 70px}a{color:#afc4ff}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.14em;color:#98aefa;font-weight:800}h1{font-size:34px;letter-spacing:-.04em;margin:5px 0}h2{font-size:21px;margin:29px 0 12px}.lead{color:#a8b8d0;margin:0;max-width:780px}.link{display:inline-block;margin-top:14px;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.card{border:1px solid #304260;border-radius:15px;padding:20px;background:#121d2f;min-width:0}.card h3{margin:7px 0 5px;font-size:17px}.card p{color:#b2c0d6;margin:8px 0}.tag{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#93e3bd}.tag.pending{color:#ffcb8c}.meta{font-size:12px;color:#8fa3c0;overflow-wrap:anywhere}.empty{border:1px dashed #384a68;padding:20px;border-radius:13px;color:#99a9c2}@media(max-width:720px){.grid{grid-template-columns:1fr}main{padding:28px 15px}}</style></head><body><?=adminShellHeader('settings')?><main><span class="eyebrow">Konfiguracja projektów</span><h1>Katalog szablonów</h1><p class="lead">Planista wybiera szablon tylko wtedy, gdy pasuje do zatwierdzonego zakresu. Gdy projekt wymaga innej technologii lub struktury, zapisuje propozycję nowego szablonu. Po zbudowaniu ogólnego szablonu przez osobnego agenta Codex infrastruktura sprawdza prywatne repozytorium i CI przed aktywacją.</p><a class="link" href="/api/project-settings.php">← Ustawienia systemu</a><h2>Aktywne szablony (<?=count($active)?>)</h2><?php if(!$active):?><div class="empty">Brak aktywnych szablonów.</div><?php else:?><div class="grid"><?php foreach($active as $item):?><article class="card"><span class="tag">Gotowy do wyboru</span><h3><?=catalogEsc($item['name'])?></h3><p><?=catalogEsc($item['description'])?></p><p class="meta">Technologia: <?=catalogEsc($item['stack'])?><br>GitHub: <?=catalogEsc($item['repo_owner'].'/'.$item['repo_name'])?><br>ID: <?=catalogEsc($item['id'])?></p></article><?php endforeach?></div><?php endif?><h2>Propozycje nowych szablonów (<?=count($proposed)?>)</h2><?php if(!$proposed):?><div class="empty">Gdy plan wykaże znaczącą różnicę, propozycja pojawi się tutaj.</div><?php else:?><div class="grid"><?php foreach($proposed as $item):?><article class="card"><span class="tag pending">Oczekuje na przygotowanie</span><h3><?=catalogEsc($item['name'])?></h3><p><?=catalogEsc($item['reason'])?></p><p class="meta">Proponowana technologia: <?=catalogEsc($item['stack'])?><br>Docelowe repozytorium: <?=catalogEsc($item['repo_owner'].'/'.$item['repo_name'])?><?php if($item['source_session']):?><br><a href="/api/project-case.php?session=<?=catalogEsc($item['source_session'])?>">Zobacz sprawę źródłową</a><?php endif?><br>ID: <?=catalogEsc($item['id'])?></p></article><?php endforeach?></div><?php endif?></main></body></html>
